----------------------------------------------------------------------
-- KEY GENERATION
----------------------------------------------------------------------
local ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789" -- no I/O/0/1, less support tickets

local function hash32(s)
    local h = 5381
    for i = 1, #s do
        h = (h * 33 + s:byte(i)) % 4294967296
    end
    return h
end

local function chunk(seed, len)
    local out = {}
    local h = seed
    for _ = 1, len do
        -- multiplier kept under 2^21 so h * m stays exact in doubles
        h = (h * 1664525 + 1013904223) % 4294967296
        local idx = (math.floor(h / 65536) % #ALPHABET) + 1
        out[#out + 1] = ALPHABET:sub(idx, idx)
    end
    return table.concat(out)
end

local function todayStamp()
    local t = os.date("!*t")
    return string.format("%04d%02d%02d", t.year, t.month, t.day)
end

local function keyForDay(stamp)
    local base = CONFIG.SALT .. "|" .. stamp .. "|SOLO"
    return table.concat({
        chunk(hash32(base .. "#a"), 4),
        chunk(hash32(base .. "#b"), 4),
        chunk(hash32(base .. "#c"), 4),
    }, "-")
end

local TODAY_KEY = keyForDay(todayStamp())

if _G.SOLO_KEY_DEBUG then
    warn("[SOLO HUB] Key for " .. todayStamp() .. " (UTC): " .. TODAY_KEY)
end

local function normalize(s)
    return (tostring(s or ""):upper():gsub("%s", ""))
end

local function isValid(input)
    local k = normalize(input)
    if k == "" then return false end
    if k == TODAY_KEY then return true end
    for _, perm in ipairs(CONFIG.Permanent) do
        if k == normalize(perm) then return true end
    end
    return false
end

----------------------------------------------------------------------
-- HELPERS
----------------------------------------------------------------------
local function copyLink()
    local ok = pcall(function()
        (setclipboard or toclipboard or (syn and syn.write_clipboard))(CONFIG.Discord)
    end)
    return ok
end

local function openLink()
    pcall(function() GuiService:OpenBrowserWindow(CONFIG.Discord) end)
end

local function readSaved()
    if not (CONFIG.RememberKey and isfile and readfile) then return nil end
    local ok, data = pcall(function()
        if isfile(CONFIG.KeyFile) then return readfile(CONFIG.KeyFile) end
    end)
    return ok and data or nil
end

local function writeSaved(key)
    if not (CONFIG.RememberKey and writefile) then return end
    pcall(function()
        if makefolder and not (isfolder and isfolder("Solo")) then makefolder("Solo") end
        writefile(CONFIG.KeyFile, key)
    end)
end

local function launchHub()
    local ok, err = pcall(function()
        loadstring(game:HttpGet(CONFIG.HUB_URL))()
    end)
    if not ok then
        warn("[SOLO HUB] Failed to load hub: " .. tostring(err))
    end
end

----------------------------------------------------------------------
-- LOGO  (same artwork the hub uses; written to disk then loaded as an
--        asset. Falls back to a drawn monogram if the executor has no
--        getcustomasset.)
----------------------------------------------------------------------
local LOGO_B64 = ""

local function logoAsset()
    if not (writefile and getcustomasset) then return nil end
    local ok, id = pcall(function()
        if makefolder and isfolder and not isfolder("Solo") then makefolder("Solo") end
        local path = "Solo/logo.png"
        if not (isfile and isfile(path)) then
            local decoded = (crypt and crypt.base64 and crypt.base64.decode)
                or (crypt and crypt.base64decode)
                or (syn and syn.crypt and syn.crypt.base64 and syn.crypt.base64.decode)
                or base64_decode
            if not decoded then return nil end
            writefile(path, decoded(LOGO_B64))
        end
        return getcustomasset(path)
    end)
    return ok and id or nil
end

