-- buttons
local function makeButton(text, y, filled)
    local b = Instance.new("TextButton")
    b.Position = UDim2.fromOffset(26, y)
    b.Size = UDim2.new(1, -52, 0, 40)
    b.BackgroundColor3 = filled and T.white or T.lift
    b.AutoButtonColor = false
    b.Font = Enum.Font.GothamBold
    b.Text = text
    b.TextSize = 13
    b.TextColor3 = filled and T.ink or T.text
    b.Parent = card
    corner(b, 10)
    if not filled then stroke(b, T.line, 1, 0.35) end

    local baseColor = b.BackgroundColor3
    b.MouseEnter:Connect(function()
        tween(b, 0.15, { BackgroundColor3 = filled and Color3.fromRGB(226, 226, 236) or Color3.fromRGB(38, 38, 46) })
    end)
    b.MouseLeave:Connect(function()
        tween(b, 0.15, { BackgroundColor3 = baseColor })
    end)
    return b
end

