----------------------------------------------------------------------
-- BEHAVIOUR
----------------------------------------------------------------------
local function dismiss()
    tween(shade, 0.25, { BackgroundTransparency = 1 })
    tween(card, 0.25, { Size = UDim2.fromOffset(440, 0), BackgroundTransparency = 1 })
    task.delay(0.3, function() gui:Destroy() end)
end

local function shake()
    local x = card.Position.X
    for i = 1, 3 do
        card.Position = UDim2.new(x.Scale, x.Offset - 7, card.Position.Y.Scale, card.Position.Y.Offset)
        task.wait(0.04)
        card.Position = UDim2.new(x.Scale, x.Offset + 7, card.Position.Y.Scale, card.Position.Y.Offset)
        task.wait(0.04)
    end
    card.Position = UDim2.new(x.Scale, x.Offset, card.Position.Y.Scale, card.Position.Y.Offset)
end

local busy = false
local function attempt(key)
    if busy then return end
    busy = true

    verifyBtn.Text = "CHECKING..."
    say("Validating key...", T.dim)
    task.wait(0.55)

    if isValid(key) then
        verifyBtn.Text = "ACCESS GRANTED"
        tween(verifyBtn, 0.2, { BackgroundColor3 = T.good })
        say("Key accepted - launching " .. CONFIG.Brand .. "...", T.good)
        writeSaved(normalize(key))
        task.wait(0.7)
        dismiss()
        task.wait(0.35)
        launchHub()
        return
    end

    busy = false
    verifyBtn.Text = "VERIFY KEY"
    say("Invalid or expired key. Get a fresh one in the Discord.", T.bad)
    tween(boxLine, 0.15, { Color = T.bad, Transparency = 0 })
    task.spawn(shake)
    task.delay(1.6, function()
        if boxLine.Parent then tween(boxLine, 0.25, { Color = T.line, Transparency = 0.2 }) end
    end)
end

verifyBtn.MouseButton1Click:Connect(function() attempt(input.Text) end)
input.FocusLost:Connect(function(enter) if enter then attempt(input.Text) end end)

getBtn.MouseButton1Click:Connect(function()
    local copied = copyLink()
    openLink()
    getBtn.Text = copied and "LINK COPIED" or "OPEN DISCORD"
    say("Join the server, grab today's key from #keys, paste it above.", T.text)
    task.delay(2.2, function()
        if getBtn.Parent then getBtn.Text = "GET KEY  -  JOIN DISCORD" end
    end)
end)

close.MouseButton1Click:Connect(dismiss)

----------------------------------------------------------------------
-- RESPONSIVE SIZING
--   The layout is authored at 440x436 and scaled down: a touch tighter
--   on desktop, and on phones shrunk to fit the viewport with margins.
----------------------------------------------------------------------
local BASE_W, BASE_H = 440, 436

local scale = Instance.new("UIScale")
scale.Parent = card

local function fitScale()
    local vp = workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize
    if not vp or vp.X <= 0 then return 0.84 end

    local touch = UserInput.TouchEnabled and not UserInput.KeyboardEnabled
    local target = touch and 0.72 or 0.84

    -- never let the card spill off a small screen
    local maxW = (vp.X - 40) / BASE_W
    local maxH = (vp.Y - 40) / BASE_H
    return math.clamp(math.min(target, maxW, maxH), 0.46, 0.9)
end

scale.Scale = fitScale()

if workspace.CurrentCamera then
    workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(function()
        if scale.Parent then
            tween(scale, 0.2, { Scale = fitScale() })
        end
    end)
end

